def validate_preference(record):
    required = ("prompt", "chosen", "rejected")
    if any(not isinstance(record.get(key), str) or not record[key].strip() for key in required):
        return False
    if record["chosen"].strip() == record["rejected"].strip():
        return False
    return True

record = {"prompt": "Explain overfitting.", "chosen": "A model fits training data too closely.", "rejected": "Overfitting always improves generalization."}
print(validate_preference(record))
